class Solution {
public:
    int xorUpTo(int m) {
        if (m < 0) return 0;
        switch (m % 4) {
            case 0: return m;
            case 1: return 1;
            case 2: return m + 1;
            default: return 0;
        }
    }

    int xorOperation(int n, int start) {
        int s = start / 2;
        int e = s + n - 1;
        int high = (xorUpTo(e) ^ xorUpTo(s - 1)) << 1;
        int low = (n & 1) & (start & 1);
        return high | low;
    }
};
